INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c9b7-74d0-8a76-fe0cc7da70e9'::uuid, '019f9df7-a2a2-7899-9f80-1aed5da88c11'::uuid, 'A machine produces 18 chocolate boxes, 25 vanilla boxes and 12 strawberry boxes. The production costs per box are $2.80, $3.40 and $4.20 respectively. Find the total production cost using matrices.', '$185.80', 'Total cost = [18, 25, 12] × [2.80, 3.40, 4.20]ᵀ = 18(2.80) + 25(3.40) + 12(4.20) = 50.40 + 85.00 + 50.40 = $185.80.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.311Z'::timestamptz, '2026-08-15T07:50:40.311Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c9c8-7713-8cb7-385a6c900a2e'::uuid, '019f9df7-a2a2-7930-a717-cd252273c91f'::uuid, 'A grouped frequency table records waiting times: 0 < t ≤ 20 mins (5 people), 20 < t ≤ 40 mins (12 people), 40 < t ≤ 60 mins (18 people), 60 < t ≤ 80 mins (5 people). Estimate the mean waiting time.', '43.5 minutes', 'Midpoints: 10, 30, 50, 70. Estimated mean = (5×10 + 12×30 + 18×50 + 5×70) ÷ 40 = 1740 ÷ 40 = 43.5 minutes.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.328Z'::timestamptz, '2026-08-15T07:50:40.328Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c9d9-744d-9811-e07e81b6e51d'::uuid, '019f9df7-a2a2-7930-a717-cd252273c91f'::uuid, 'The mean waiting time for a group is 43.5 minutes. If every recorded waiting time is reduced by 4 minutes, state the new mean and explain what happens to the standard deviation.', 'New mean = 39.5 minutes; standard deviation remains unchanged.', 'Subtracting 4 from every value decreases the mean by 4. The spread of the data does not change, so the standard deviation remains unchanged.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.345Z'::timestamptz, '2026-08-15T07:50:40.345Z'::timestamptz) ON CONFLICT (id) DO NOTHING;